/* SIMD interpolate - processes 4 INT16 channels at once.
   Loads 4 lanes from a and b; performs (a*(1<<SHIFT - shift) + b*shift) >> SHIFT */
static inline __m128i
simd_interpolate4(const INT16 *a, const INT16 *b, __m128i mm_shift, __m128i mm_inv_shift) {
    __m128i va = _mm_loadl_epi64((const __m128i *)a);  /* loads 64 bits = 4x INT16 */
