    __m128i vb = _mm_loadl_epi64((const __m128i *)b);
    __m128i diff = _mm_sub_epi16(vb, va);
    /* mulhrs computes ((diff * shift) + 0x4000) >> 15 */
    __m128i mul = _mm_mulhrs_epi16(diff, mm_shift);
