static inline __m128i
simd_interpolate4(const INT16 *a, const INT16 *b, __m128i mm_shift32, __m128i mm_inv_shift32) {
    __m128i va = _mm_loadl_epi64((const __m128i *)a);  /* 4 INT16 */
    __m128i vb = _mm_loadl_epi64((const __m128i *)b);
    /* sign-extend to INT32 */
    __m128i va32 = _mm_cvtepi16_epi32(va);
    __m128i vb32 = _mm_cvtepi16_epi32(vb);
    /* multiply */
    __m128i p1 = _mm_mullo_epi32(va32, mm_inv_shift32);
    __m128i p2 = _mm_mullo_epi32(vb32, mm_shift32);
    __m128i sum = _mm_add_epi32(p1, p2);
    sum = _mm_srai_epi32(sum, SHIFT_BITS);
